package in.mohammad.ramiz.confess.data.security;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.nio.charset.StandardCharsets;

import org.junit.Test;

/**
 * Vectors generated by the server's SecurityManager (app/core/security.py), so a
 * change on either side that breaks request signing fails here first.
 */
public class RequestSignerTest {

    private static final byte[] KEY = RequestSigner.b64urlDecode("EFuQyPxPdMHPoOOsfUi-ExiocK3NRbKGm4zfAm7MaUE");
    private static final String SID = "6f1c2b1e-0000-4000-8000-000000000001";
    private static final String NONCE = "nonceNonceNonce_-1234";
    private static final long TS = 1760000000L;

    private static String sign(String method, String path, String query, byte[] body) {
        return RequestSigner.requestSignature(KEY, method, RequestSigner.canonicalPath(path, query), TS, NONCE,
                RequestSigner.sha256Hex(body), SID);
    }

    @Test
    public void postWithUtf8Body() {
        byte[] body = "{\"text\":\"hello ✨\",\"commentsEnabled\":true}".getBytes(StandardCharsets.UTF_8);
        assertEquals("qRdICp658P6ZxE53tHrARARLygssbxDgdETjS6OU60I", sign("POST", "/api/v2/posts", null, body));
    }

    @Test
    public void getWithQueryBehindProxyPrefix() {
        assertEquals("UkgTN4aDur1867VunSBXFYGkOqpHYI4hRvsPOa_MYsM",
                sign("GET", "/prefix/api/v2/posts/feed", "sort=top&cursor=abc%3D%3D&limit=15", new byte[0]));
    }

    @Test
    public void deleteWithoutBody() {
        assertEquals("zoenShwBpB2fWFwBUkgdctUBBdy6ruw44wybMtesR2Y", sign("delete", "/api/v2/users/me", "", new byte[0]));
    }

    @Test
    public void responseSignature() {
        String s = RequestSigner.responseSignature(KEY, NONCE, 200,
                RequestSigner.sha256Hex("{\"success\":true}".getBytes(StandardCharsets.UTF_8)));
        assertEquals("DFENFGJLHJok0D3d-F2qoZ8hGyI7shdZW3uFLPx6wlw", s);
        assertFalse(RequestSigner.same(s, RequestSigner.responseSignature(KEY, NONCE, 201,
                RequestSigner.sha256Hex("{\"success\":true}".getBytes(StandardCharsets.UTF_8)))));
    }

    @Test
    public void noncesAreFreshAndValid() {
        String a = RequestSigner.newNonce();
        String b = RequestSigner.newNonce();
        assertTrue(a.matches("^[A-Za-z0-9_\\-]{16,64}$"));
        assertFalse(a.equals(b));
    }
}
